'use strict';

// MODULES //

var join = require( 'path' ).join;
var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var byteLength = require( './../../../byte_length.js' );


// VARIABLES //

var FILE_PATH = join( __dirname, 'vega.min.js' );


// MAIN //

/**
* Callback invoked upon receiving an HTTP request.
*
* @private
* @param {Object} request - request object
* @param {Object} response - response object
* @returns {void}
*/
function handler( request, response ) {
	var body = readFileSync( FILE_PATH );
	response.statusCode = 200;
	response.setHeader( 'Content-Type', 'text/javascript' );
	response.setHeader( 'Content-Length', byteLength( body ) );
	response.end( body );
}


// EXPORTS //

module.exports = handler;
